def compareEncoded(a, b):
    i = j = 0
    ra = a[0][1]
    rb = b[0][1]
    while i < len(a) and j < len(b):
        ca, cb = a[i][0], b[j][0]
        if ca != cb:
            return -1 if ca < cb else 1
        t = min(ra, rb)
        ra -= t
        rb -= t
        if ra == 0:
            i += 1
            if i < len(a):
                ra = a[i][1]
        if rb == 0:
            j += 1
            if j < len(b):
                rb = b[j][1]
    if i == len(a) and j == len(b):
        return 0
    return -1 if i == len(a) else 1
